//! Golden parity tests: the Rust port must match what the REAL Python
//! TagGUI does, fixture by fixture. Fixtures are generated by
//! `tools/gen_golden.py` running the actual Python app - see PORT_GUIDE.md.

use std::path::{Path, PathBuf};

use serde::Deserialize;
use tg_core::filter::Filter;
use tg_core::sidecar::{parse_tags, write_tags};
use tg_core::tags::{add_caption_to_tags, CaptionPosition};

fn golden_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("golden")
}

// ---------------------------------------------------------------------------
// sidecar.json - how the Python model parses caption files.
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct SidecarFixture {
    tag_separator: String,
    inputs: std::collections::BTreeMap<String, Option<Vec<u8>>>,
    results: Vec<SidecarResult>,
}

#[derive(Deserialize)]
struct SidecarResult {
    name: String,
    tags: Vec<String>,
    has_caption_file: bool,
}

#[test]
fn sidecar_parsing_matches_python() {
    let fixture: SidecarFixture =
        serde_json::from_str(&std::fs::read_to_string(golden_dir().join("sidecar.json")).unwrap())
            .unwrap();
    assert_eq!(fixture.tag_separator, ", ");
    assert_eq!(fixture.inputs.len(), fixture.results.len());
    for result in &fixture.results {
        let raw = fixture.inputs.get(&result.name).unwrap();
        let tags = match raw {
            Some(bytes) => {
                let caption = String::from_utf8_lossy(bytes);
                parse_tags(&caption, &fixture.tag_separator)
            }
            None => Vec::new(),
        };
        assert_eq!(tags, result.tags, "sidecar mismatch for {}", result.name);
        let has_caption_file = raw.is_some();
        assert_eq!(
            has_caption_file, result.has_caption_file,
            "has_caption_file mismatch for {}",
            result.name
        );
    }
}

// ---------------------------------------------------------------------------
// caption_positions.json - add_caption_to_tags for every position.
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct PositionsFixture {
    tag_separator: String,
    cases: Vec<PositionCase>,
}

#[derive(Deserialize)]
struct PositionCase {
    position: String,
    tags: Vec<String>,
    caption: String,
    result: Vec<String>,
}

fn parse_position(text: &str) -> CaptionPosition {
    text.parse()
        .unwrap_or_else(|_| panic!("unknown position {text}"))
}

#[test]
fn caption_positions_match_python() {
    let fixture: PositionsFixture = serde_json::from_str(
        &std::fs::read_to_string(golden_dir().join("caption_positions.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(fixture.tag_separator, ", ");
    for case in &fixture.cases {
        let result = add_caption_to_tags(
            &case.tags,
            &case.caption,
            parse_position(&case.position),
            &fixture.tag_separator,
        );
        assert_eq!(
            result, case.result,
            "add_caption_to_tags mismatch: position={}, tags={:?}, \
                   caption={:?}",
            case.position, case.tags, case.caption
        );
    }
}

// ---------------------------------------------------------------------------
// sidecar_write.json - the exact bytes the Python model writes to disk.
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct WriteFixture {
    written: Vec<WriteCase>,
}

#[derive(Deserialize)]
struct WriteCase {
    #[allow(dead_code)]
    path: String,
    tags: Vec<String>,
    bytes: Vec<u8>,
}

#[test]
fn sidecar_writes_match_python_byte_for_byte() {
    let fixture: WriteFixture = serde_json::from_str(
        &std::fs::read_to_string(golden_dir().join("sidecar_write.json")).unwrap(),
    )
    .unwrap();
    let dir = tempfile::tempdir().unwrap();
    for case in &fixture.written {
        let image_path = dir.path().join(&case.path);
        write_tags(&image_path, &case.tags, ", ").unwrap();
        let actual = std::fs::read(image_path.with_extension("txt")).unwrap();
        assert_eq!(
            actual, case.bytes,
            "sidecar write mismatch for {} (expected {:?}, got {:?})",
            case.path, case.bytes, actual
        );
    }
}

// ---------------------------------------------------------------------------
// filters.json - parse acceptance AND image-match results for a matrix of
// filter strings against synthetic images, straight from the Python
// grammar (pyparsing) and evaluator (ProxyImageListModel).
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct FiltersFixture {
    images: Vec<FixtureImage>,
    filters: Vec<FilterCase>,
}

#[derive(Deserialize)]
struct FixtureImage {
    path: String,
    dimensions: Option<(u32, u32)>,
    file_size: Option<u64>,
    tags: Vec<String>,
}

#[derive(Deserialize)]
struct FilterCase {
    filter: String,
    parses: bool,
    matches: Vec<bool>,
}

#[test]
fn filters_match_python_parse_and_evaluation() {
    let fixture: FiltersFixture =
        serde_json::from_str(&std::fs::read_to_string(golden_dir().join("filters.json")).unwrap())
            .unwrap();
    for case in &fixture.filters {
        let parsed = Filter::parse(&case.filter);
        assert_eq!(
            parsed.is_some(),
            case.parses,
            "parse acceptance mismatch for {:?}",
            case.filter
        );
        if !case.parses {
            continue;
        }
        let filter = parsed.unwrap();
        for (image, expected) in fixture.images.iter().zip(&case.matches) {
            let path = PathBuf::from(&image.path);
            let input = tg_core::filter::FilterInput {
                path: &path,
                dimensions: image.dimensions,
                file_size: image.file_size,
                tags: &image.tags,
                tag_separator: ", ",
                // The fixture matrix deliberately contains no `tokens:`
                // filter (the Python oracle uses a fake tokenizer).
                token_counter: None,
            };
            assert_eq!(
                filter.matches(&input),
                *expected,
                "filter {:?} mismatch for {}",
                case.filter,
                image.path
            );
        }
    }
}
